if(PHP_SAPI!=='cli'||getenv('SPP_DB_PORT')!=='58246'||getenv('SPP_TEST_ALLOW_MUTATION')!=='1')throw new RuntimeException('Private fixture required.');
$_SESSION=['admin_id'=>1,'admin_role'=>'super_admin','active_unit_id'=>1];require __DIR__.'/../koneksi.php';require_once __DIR__.'/../includes/legacy_transactions.php';$db=$koneksi;if($db->query('SELECT @@server_uuid')->fetch_row()[0]!=='9d552e39-cbe6-11f1-9a5e-0a0027000012')throw new RuntimeException('Unexpected server.');$checks=[];$check=function($ok,$label)use(&$checks){if(!$ok)throw new RuntimeException($label);$checks[]=$label;};$p=lop_record($db,'payment',(int)lf_one($db,"SELECT p.id FROM legacy_op_payments p JOIN legacy_op_owners o ON o.id=p.owner_id AND o.unit_id=p.unit_id WHERE p.source_table='bayar_du' AND p.cancelled=0 AND p.total>0 AND p.source_period IS NOT NULL AND o.state='ready' AND NOT EXISTS(SELECT 1 FROM legacy_op_obligations b WHERE b.owner_id=p.owner_id AND b.category='daftar_ulang' AND b.period=p.source_period) LIMIT 1")['id']);$native=(int)lf_one($db,'SELECT COUNT(*) n FROM bayar')['n'];$bills=(int)lf_one($db,'SELECT COUNT(*) n FROM tagihan_biaya_lain')['n'];$key=bin2hex(random_bytes(32));$db->begin_transaction();try{
 $principal=lf_cents($p['total'])+10000;lf_query($db,"INSERT INTO legacy_op_obligations(unit_id,owner_id,category,period,principal,remaining,evidence) VALUES(?,?,'daftar_ulang',?,?,'100.00',?)",[1,$p['owner_id'],$p['source_period'],lf_money($principal),'Isolated verified obligation']);$oid=(int)$db->insert_id;$items=$p['items'];$items[0]['obligation_id']=$oid;lf_query($db,'UPDATE legacy_op_payments SET items=? WHERE id=?',[lf_json($items),$p['id']]);$p=lop_record($db,'payment',(int)$p['id']);$input=['date'=>$p['source_date'],'period'=>$p['source_period'],'method'=>'VA koreksi teruji','note'=>$p['note'],'items'=>$items,'cancelled'=>true,'reason'=>'Pembatalan kewajiban terverifikasi pada salinan','preview_expires'=>time()+300,'confirmation'=>'SIMPAN KOREKSI'];$preview=lop_correction_preview($db,1,1,'payment',(int)$p['id'],(int)$p['version'],$input);lop_correction_apply($db,1,1,'payment',(int)$p['id'],(int)$p['version'],$input,$preview['digest'],$key,false);$ob=lf_one($db,'SELECT * FROM legacy_op_obligations WHERE id=?',[$oid]);$check(lf_cents($ob['remaining'])===$principal,'Cancellation restores verified obligation remaining');$check((int)lf_one($db,'SELECT COUNT(*) n FROM bayar')['n']===$native&&(int)lf_one($db,'SELECT COUNT(*) n FROM tagihan_biaya_lain')['n']===$bills,'Cancellation issues no unrelated payment or bill');$check(lop_record($db,'payment',(int)$p['id'])['method']==='VA koreksi teruji','Method correction shares financial transaction');$retry=lop_correction_apply($db,1,1,'payment',(int)$p['id'],(int)$p['version'],$input,$preview['digest'],$key,false);$check($retry['replayed'],'Bound cancellation retry applies once');
}finally{$db->rollback();}
$after=lop_record($db,'payment',(int)$p['id']);$check(!$after['cancelled']&&!lf_one($db,'SELECT id FROM legacy_op_audit WHERE request_key=?',[$key]),'Rollback restores bound payment and audit');$result=['checks'=>count($checks),'passed'=>$checks];file_put_contents(getenv('SPP_UNIFICATION_OBLIGATION_RESULT'),json_encode($result,JSON_PRETTY_PRINT));echo json_encode($result,JSON_PRETTY_PRINT);
